        best = None
        for dx, dy in dirs:
            nx, ny = sx + dx, sy + dy
            if not inb(nx, ny):
                continue
            pen = 0
            if (nx, ny) in obstacles:
                pen += 10
            if (nx, ny) in opp_terr:
                pen += 0 if prefer_opp_enter else 1
            # Prefer lower chebyshev distance, then lower movement, then deterministic tie-break
            dist = max(abs(nx - tx), abs(ny - ty))
