            if best is None or key < best[0]:
                best = (key, dx, dy)
        return [best[1], best[2]] if best else [0, 0]

    # Prefer capturing adjacent unclaimed from our territory
    if self_terr and unclaimed:
        frontier = []
        for x, y in self_terr:
            for dx, dy in dirs:
                nx, ny = x + dx, y + dy
